use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut out: Vec<FeedItem> = Vec::with_capacity(items.len());
        for item in items {
            // Drop items already recorded in the 'seen' store.
            if state_read::get(&item.id).is_some() {
                continue;
            }
            // Drop duplicates within this batch as well.
            if out.iter().any(|kept| kept.id == item.id) {
                continue;
            }
            out.push(item);
        }
        out
    }
}

export!(Node);
